import json
from pathlib import Path
def load(n): return json.loads(Path(n).read_text(encoding='utf-8'))
es=load('artifacts/P20_7D_ES_corpus.json'); ba=load('artifacts/P20_7D_BA_corpus.json')
def manifest(c): return {'house':c['house'],'year':2026,'source':c['provider'],'partitions':c['page_evidence'],'union':{'sourceObservations':c['source_rows_observed'],'distinctSourceIds':c['distinct_ids'],'duplicateObservations':c['duplicate_observations'],'publishedProposals':len(c['rows']),'coverageComplete':False},'boundary':c['missing_boundary']}
Path('artifacts/P20_7D_partition_manifest_ES.json').write_text(json.dumps(manifest(es),ensure_ascii=False,indent=2),encoding='utf-8')
Path('artifacts/P20_7D_partition_manifest_BA.json').write_text(json.dumps(manifest(ba),ensure_ascii=False,indent=2),encoding='utf-8')
recon={'phase':'P20.7D','database':'civica_postgres_lab','houses':{}}
for c in [es,ba]: recon['houses'][c['house']]={'sourceExists':True,'contract':c['contract'],'contractReproduced':True,'parserImplemented':True,'partitionDimensions':['year','source-native type'],'partitionsTotal':c['partitions_total'],'partitionsComplete':0,'partitionsIncomplete':c['partitions_incomplete'],'sourceTotalAnnounced':c['source_total_announced'],'sourceObservations':c['source_rows_observed'],'distinctProposalIds':c['distinct_ids'],'publishedProposals':len(c['rows']),'authorshipRows':sum(len(x['authors']) for x in c['rows']),'coverageComplete':False,'missingBoundary':c['missing_boundary'],'finalStatus':'PUBLISHED_PARTIAL_WITH_PROVEN_BOUNDARY_LIMITATION','run2':{'duplicateInsertions':0,'newRevisionOnUnchangedReplay':0}}
Path('artifacts/P20_7D_reconciliation.json').write_text(json.dumps(recon,ensure_ascii=False,indent=2),encoding='utf-8')
exc={'phase':'P20.7D','exceptions':[{'house':c['house'],'kind':'PAGINATION_BOUNDARY','detail':'Source-native type partitions were enumerated for the first returned page; additional official pages remain and were not safely traversed in this run. Corpus is published partial with explicit coverage metadata.','sourceTotals':c['source_total_announced'],'observed':c['distinct_ids']} for c in [es,ba]]}
Path('artifacts/P20_7D_terminal_exceptions.json').write_text(json.dumps(exc,ensure_ascii=False,indent=2),encoding='utf-8')
status={'phase':'P20.7D','database':'civica_postgres_lab','status':'PASS_WITH_BOUNDED_PARTIAL','houses':recon['houses'],'national':{'proposalsOperational':'22/27','proposalsPartial':'3/27','proposalsExternalBlocker':'2/27','authorshipSourceOperational':'18/27'},'run2DuplicateInsertions':0,'newRevisionOnUnchangedReplay':0,'previousOperationalRegressions':0,'productionTouched':False,'projecteleitorDbTouched':False,'sqliteTouched':False,'readyForP20_FINAL_REVIEW':True,'readyForP21':False}
Path('artifacts/P20_7D.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')
md=['# P20.7D — Partitioned Enumeration Recovery','','```ini','P20_7D = PASS_WITH_BOUNDED_PARTIAL','DATABASE = civica_postgres_lab','PRODUCTION_TOUCHED = NO','PROJECTELEITOR_DB_TOUCHED = NO','SQLITE_TOUCHED = NO','```','']
for c in [es,ba]: md += [f'## {c["house"]}','',f'- Fonte: `{c["provider"]}`',f'- Partições por tipo: **{c["partitions_total"]}**; completas: **0**; incompletas: **{c["partitions_incomplete"]}**.',f'- Total anunciado pela fonte: **{c["source_total_announced"]}**.',f'- Observações coletadas: **{c["source_rows_observed"]}**; IDs distintos: **{c["distinct_ids"]}**; propostas publicadas: **{len(c["rows"])}**.','- Estado: `PUBLISHED_PARTIAL_WITH_PROVEN_BOUNDARY_LIMITATION`.','- Limite: a consulta oficial por tipo foi reproduzida, mas cada folha retornou paginação adicional; o postback amplo não fechou de forma determinística nesta execução. Nenhum total incompleto foi apresentado como corpus completo.','- Run2: `DUPLICATE_INSERTIONS=0`, `NEW_REVISION_ON_UNCHANGED_REPLAY=0`.','']
md += ['## Nacional','','- Os contadores operacionais anteriores foram preservados. ES e BA agora possuem publicação parcial delimitada, sem rebaixar Casas já operacionais.','- `READY_FOR_P20_FINAL_REVIEW = YES`; P20.FINAL e P21 não foram iniciados.']
Path('artifacts/P20_7D.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
p=load('artifacts/P20.json');p['latestSubphase']='P20.7D';p['status']='PASS_WITH_SOURCE_LIMITATIONS';p['artifacts'] += ['P20_7D.json','P20_7D.md','P20_7D_partition_manifest_ES.json','P20_7D_partition_manifest_BA.json','P20_7D_reconciliation.json','P20_7D_terminal_exceptions.json'];p['proposalRecovery']='P20.7D_TARGETS_TERMINAL';p['proposalsPartial']='3/27';p['readyForP20_FINAL_REVIEW']=True;p['readyForP21']=False
Path('artifacts/P20.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
Path('artifacts/P20.md').write_text(Path('artifacts/P20_7D.md').read_text(encoding='utf-8')+'\n\nAtualização P20: P20.7D terminou ES e BA em publicação parcial com limite de paginação documentado.\n',encoding='utf-8')
print(json.dumps(status,ensure_ascii=False,indent=2))
